import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1788526325000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to “Tools”">​</a></h1><p>Eleven tools: six read, five write. The write tools are <strong>not registered</strong> unless <code>IMAP_READ_ONLY=false</code> — and it defaults to <code>true</code>, so an unconfigured server offers the six read tools alone.</p><p>Beyond that, <code>IMAP_ALLOW_TOOLS</code> and <code>IMAP_DENY_TOOLS</code> narrow the list further, and <code>IMAP_ALLOW_TOOLS=essential</code> selects the six marked <strong>essential</strong> below — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><h2 id="read-tools" tabindex="-1">Read tools <a class="header-anchor" href="#read-tools" aria-label="Permalink to “Read tools”">​</a></h2><p>Registered always.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><code>list_mailboxes</code></td><td>The folder tree, with the special-use flags the server reports (<code>\\Drafts</code>, <code>\\Sent</code>, …). <strong>essential</strong></td></tr><tr><td><code>list_new_messages</code></td><td>What the assistant has not seen yet, tracked with its own IMAP keyword rather than <code>\\Seen</code>. <strong>essential</strong></td></tr><tr><td><code>list_messages</code></td><td>Search and list a mailbox: by sender, subject, date range, flags. <strong>essential</strong></td></tr><tr><td><code>get_message</code></td><td>One message, body fenced as untrusted content. <strong>essential</strong></td></tr><tr><td><code>get_attachments</code></td><td>Attachment metadata, small ones inline, and the text of a PDF or Office file with <code>mode: &quot;text&quot;</code></td></tr><tr><td><code>get_server_info</code></td><td>Capabilities, the mailbox in use, and whether the write tools are registered</td></tr></tbody></table><h2 id="write-tools" tabindex="-1">Write tools <a class="header-anchor" href="#write-tools" aria-label="Permalink to “Write tools”">​</a></h2><p>Registered only when <code>IMAP_READ_ONLY=false</code>.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><code>set_message_flags</code></td><td>Set or clear flags and keywords — read, flagged, and the assistant&#39;s own. <strong>essential</strong></td></tr><tr><td><code>move_messages</code> 👤</td><td>Move or copy messages between folders. <strong>essential</strong></td></tr><tr><td><code>delete_messages</code> 👤</td><td>Delete: sets <code>\\Deleted</code> and expunges. Not the same as moving to Trash</td></tr><tr><td><code>save_draft</code></td><td>Append a draft to the drafts folder. This server never <strong>sends</strong> anything</td></tr><tr><td><code>manage_mailbox</code> 👤</td><td>Create, rename and delete folders — 👤 for <code>delete</code>, 🔒 for <code>rename</code>, nothing for <code>create</code></td></tr></tbody></table><p>👤 <strong>asks a person</strong> through MCP elicitation, a dialog the model cannot answer on its behalf. 🔒 uses the two-call <code>confirm_token</code> only. Where a 👤 tool&#39;s client cannot show a dialog it falls back to 🔒, and <code>ELICITATION=false</code> takes that fallback deliberately. See <a href="/guide/approval">Asking a person</a>.</p><p>Every tool declares an <code>outputSchema</code> and answers with <code>structuredContent</code> beside the text block, so a client can use a result without parsing prose. Every tool that reports anything out of the mailbox carries <code>untrusted: true</code> and <code>source: &quot;imap&quot;</code> as fields — only <code>get_server_info</code> and the five write tools are without it. <code>get_message</code> and a text attachment keep the nonce fence in the text block and state the same fields in the structured half; an image attachment keeps its bytes in the content block rather than repeating the base64.</p><p>Every tool declares all four MCP annotations — <code>readOnlyHint</code>, <code>destructiveHint</code>, <code>idempotentHint</code>, <code>openWorldHint</code>. <code>get_attachments</code> carries the only <em>computed</em> one in the family: it is <code>readOnlyHint: true</code> until <code>IMAP_DOWNLOAD_DIR</code> is set, because from then on it writes files.</p><h2 id="reading-a-document" tabindex="-1">Reading a document <a class="header-anchor" href="#reading-a-document" aria-label="Permalink to “Reading a document”">​</a></h2><p><code>get_attachments</code> takes a <code>mode</code>. <code>auto</code> reads small text and images inline, saves to disk where <code>IMAP_DOWNLOAD_DIR</code> is set, and otherwise extracts the text of a PDF, Word, Excel, PowerPoint or OpenDocument file. <code>inline</code> always returns the content, <code>file</code> always saves it, and <code>text</code> always extracts.</p><p><code>mode: &quot;text&quot;</code> is the only way to read a document from a client that cannot reach this server&#39;s filesystem — which is every remote one. It returns the text fenced as untrusted content, with <code>offset</code> and <code>max_chars</code> to page through anything longer than one result can hold; the answer carries <code>next_offset</code>, <code>total_chars</code> and <code>returned_chars</code>, and the notes spell out the exact follow-up call. The listing marks each part <code>extractable</code>, so the choice can be made before anything is fetched.</p><p>Spreadsheets come back as tab-separated values with a <code>== Sheet: name ==</code> heading per tab; presentations get a heading per slide.</p><p>There is no OCR. A scanned PDF has no text layer, and the refusal says so and names the two ways to get the bytes instead — rather than returning an empty string that reads like an empty document.</p><h2 id="resources-which-the-filter-does-not-cover" tabindex="-1">Resources, which the filter does not cover <a class="header-anchor" href="#resources-which-the-filter-does-not-cover" aria-label="Permalink to “Resources, which the filter does not cover”">​</a></h2><p>Attachments are also exposed as MCP <strong>resources</strong>. <code>IMAP_ALLOW_TOOLS</code> narrows <code>tools/list</code>, not <code>resources/list</code>, so a filtered server still serves those. <code>IMAP_DOWNLOAD_DIR</code> and the attachment type allowlist are what constrain them. Note that resources carry the raw bytes: the text extraction above is on the tool only, because extracted text is the sender&#39;s text and belongs inside the nonce fence, which a resource has nowhere to put.</p>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};